class Solution {
public:
    int maximumCandies(vector<int>& candies, long long k) {
        int l = 1, r = *max_element(candies.begin(), candies.end());
        int ans = 0;
        while (l <= r) {
            int mid = l + (r - l) / 2;
            long long count = 0;
            for (int c : candies) {
                count += c / mid;
            }
            if (count >= k) {
                ans = mid;
                l = mid + 1;
            } else {
                r = mid - 1;
            }
        }
        return ans;
    }
};

class Solution {
    public int maximumCandies(int[] candies, long k) {
        int l = 1, r = 0;
        for (int c : candies) r = Math.max(r, c);
        int ans = 0;
        while (l <= r) {
            int mid = l + (r - l) / 2;
            long count = 0;
            for (int c : candies) {
                count += c / mid;
            }
            if (count >= k) {
                ans = mid;
                l = mid + 1;
            } else {
                r = mid - 1;
            }
        }
        return ans;
    }
}

/**
 * @param {number[]} candies
 * @param {number} k
 * @return {number}
 */
var maximumCandies = function(candies, k) {
    let l = 1, r = Math.max(...candies);
    let ans = 0;
    const K = BigInt(k);
    while (l <= r) {
        const mid = Math.floor((l + r) / 2);
        let count = 0n;
        for (const c of candies) {
            count += BigInt(Math.floor(c / mid));
        }
        if (count >= K) {
            ans = mid;
            l = mid + 1;
        } else {
            r = mid - 1;
        }
    }
    return ans;
};
